abstract class Approval {
  constructor(protected next?: Approval) {}
  abstract approve(amount: number): string;
  protected forward(amount: number) {
    return this.next?.approve(amount) ?? 'sem aprovador';
  }
}
class TeamLead extends Approval {
  approve(amount: number): string {
    return amount <= 100 ? 'lider' : this.forward(amount);
  }
}
class Manager extends Approval {
  approve(amount: number): string {
    return amount <= 1000 ? 'gerente' : this.forward(amount);
  }
}
export function demo() {
  const chain = new TeamLead(new Manager());
  return [chain.approve(50), chain.approve(500), chain.approve(5000)];
}

class Cart {
  quantity = 0;
}
interface Command {
  execute(): void;
  undo(): void;
}
class AddUnits implements Command {
  private previous: number | undefined;
  constructor(
    private cart: Cart,
    private units: number,
  ) {}
  execute() {
    this.previous = this.cart.quantity;
    this.cart.quantity += this.units;
  }
  undo() {
    if (this.previous === undefined) throw new Error('Comando não executado');
    this.cart.quantity = this.previous;
    this.previous = undefined;
  }
}
export function demo() {
  const cart = new Cart();
  const command: Command = new AddUnits(cart, 3);
  command.execute();
  const after = cart.quantity;
  command.undo();
  return { after, undone: cart.quantity };
}

type Lesson = { title: string; children: Lesson[] };
function* depthFirst(node: Lesson): Generator<string> {
  yield node.title;
  for (const child of node.children) yield* depthFirst(child);
}
function* breadthFirst(root: Lesson): Generator<string> {
  const queue = [root];
  for (let index = 0; index < queue.length; index++) {
    const node = queue[index];
    yield node.title;
    queue.push(...node.children);
  }
}
export function demo() {
  const root: Lesson = {
    title: 'A',
    children: [
      { title: 'B', children: [{ title: 'D', children: [] }] },
      { title: 'C', children: [] },
    ],
  };
  return { depth: [...depthFirst(root)], breadth: [...breadthFirst(root)] };
}

class BookingForm {
  private people = 1;
  private capacity = 0;
  canBook = false;
  peopleChanged(value: number) {
    this.people = value;
    this.reconcile();
  }
  roomChanged(capacity: number) {
    this.capacity = capacity;
    this.reconcile();
  }
  private reconcile() {
    this.canBook = this.people > 0 && this.capacity >= this.people;
  }
}
export function demo() {
  const mediator = new BookingForm();
  const peopleInput = { change: (n: number) => mediator.peopleChanged(n) };
  const roomInput = { change: (n: number) => mediator.roomChanged(n) };
  peopleInput.change(5);
  roomInput.change(3);
  const smallRoom = mediator.canBook;
  roomInput.change(8);
  return { smallRoom, largeRoom: mediator.canBook };
}

class ScriptEditor {
  #text = '';
  write(text: string) {
    this.#text = text;
  }
  read() {
    return this.#text;
  }
  checkpoint(): () => void {
    const saved = this.#text;
    return () => {
      this.#text = saved;
    };
  }
}
export function demo() {
  const editor = new ScriptEditor();
  const history: (() => void)[] = [];
  editor.write('Introdução');
  history.push(editor.checkpoint());
  editor.write('Novo final');
  const changed = editor.read();
  history.pop()!();
  return { changed, restored: editor.read() };
}

type Listener = (available: number) => void;
class Vacancies {
  private listeners = new Set<Listener>();
  subscribe(listener: Listener) {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }
  publish(count: number) {
    for (const listener of [...this.listeners]) listener(count);
  }
}
export function demo() {
  const vacancies = new Vacancies();
  const events: string[] = [];
  const unsubscribe = vacancies.subscribe((n) => events.push(`A:${n}`));
  vacancies.subscribe((n) => events.push(`B:${n}`));
  vacancies.publish(1);
  unsubscribe();
  vacancies.publish(2);
  return events;
}

interface AccessState {
  allows(): boolean;
  toggle(): AccessState;
}
class Active implements AccessState {
  allows() {
    return true;
  }
  toggle(): AccessState {
    return new Paused();
  }
}
class Paused implements AccessState {
  allows() {
    return false;
  }
  toggle(): AccessState {
    return new Active();
  }
}
class Subscription {
  private state: AccessState = new Active();
  access() {
    return this.state.allows();
  }
  pauseOrResume() {
    this.state = this.state.toggle();
  }
}
export function demo() {
  const subscription = new Subscription();
  const values = [subscription.access()];
  subscription.pauseOrResume();
  values.push(subscription.access());
  subscription.pauseOrResume();
  values.push(subscription.access());
  return values;
}

type Agent = { name: string; pending: number };
type Routing = (agents: Agent[]) => Agent;
const firstAvailable: Routing = (agents) => agents[0];
const leastLoaded: Routing = (agents) =>
  agents.reduce((a, b) => (a.pending <= b.pending ? a : b));
class TicketRouter {
  constructor(private routing: Routing) {}
  assign(agents: Agent[]) {
    if (!agents.length) throw new Error('Sem agentes');
    return this.routing(agents).name;
  }
}
export function demo() {
  const agents = [
    { name: 'Ana', pending: 4 },
    { name: 'Bia', pending: 1 },
  ];
  return [
    new TicketRouter(firstAvailable).assign(agents),
    new TicketRouter(leastLoaded).assign(agents),
  ];
}

abstract class ContactImporter {
  protected abstract split(input: string): string[];
  run(input: string) {
    const values = this.split(input).map((value) => value.trim());
    return values.filter((value) => value.includes('@'));
  }
}
class LineImporter extends ContactImporter {
  protected split(input: string) {
    return input.split('\n');
  }
}
class SemicolonImporter extends ContactImporter {
  protected split(input: string) {
    return input.split(';');
  }
}
export function demo() {
  return [
    new LineImporter().run(' a@x.test \nsem-email'),
    new SemicolonImporter().run(' b@x.test ;outro'),
  ];
}

interface Visitor {
  text(node: TextFile): number;
  image(node: ImageFile): number;
}
interface File {
  accept(visitor: Visitor): number;
}
class TextFile implements File {
  constructor(readonly characters: number) {}
  accept(visitor: Visitor) {
    return visitor.text(this);
  }
}
class ImageFile implements File {
  constructor(readonly pixels: number) {}
  accept(visitor: Visitor) {
    return visitor.image(this);
  }
}
class StorageEstimate implements Visitor {
  text(node: TextFile) {
    return node.characters * 2;
  }
  image(node: ImageFile) {
    return node.pixels * 4;
  }
}
class FileCount implements Visitor {
  text(_node: TextFile) {
    return 1;
  }
  image(_node: ImageFile) {
    return 1;
  }
}
export function demo() {
  const files: File[] = [new TextFile(10), new ImageFile(5)];
  const sum = (visitor: Visitor) =>
    files.reduce((n, file) => n + file.accept(visitor), 0);
  return {
    estimatedBytes: sum(new StorageEstimate()),
    files: sum(new FileCount()),
  };
}
